const MONTHS={jan:1,feb:2,mär:3,mae:3,mrz:3,apr:4,mai:5,jun:6,jul:7,aug:8,sep:9,okt:10,nov:11,dez:12};
export function parseDate(text){const m=text.match(/\b(\d{1,2})\.\s*([A-Za-zÄÖÜäöü]+|\d{1,2})\.?\s*(\d{4}|\d{2})\b/);if(!m)return null;const month=MONTHS[m[2].toLowerCase().slice(0,3)]||Number(m[2]);const year=Number(m[3])+(m[3].length===2?2000:0);const d=new Date(Date.UTC(year,month-1,+m[1]));if(d.getUTCFullYear()!==year||d.getUTCMonth()!==month-1||d.getUTCDate()!==+m[1])return null;return d.toISOString().slice(0,10)}
export function parsePage(items){const texts=items.filter(i=>i.str?.trim()).map(i=>({s:i.str.trim(),x:i.transform[4],y:i.transform[5],w:i.width,vertical:Math.abs(i.transform[1])>Math.abs(i.transform[0])}));const horizontal=texts.filter(i=>!i.vertical);const lines=[];for(const t of horizontal){let line=lines.find(l=>Math.abs(l.y-t.y)<2.4);if(!line){line={y:t.y,items:[]};lines.push(line)}line.items.push(t)}lines.forEach(l=>l.items.sort((a,b)=>a.x-b.x));const dates=lines.map(l=>({...l,date:parseDate(l.items.map(i=>i.s).join(' '))})).filter(l=>l.date&&l.items.length>=3);if(!dates.length)return [];const firstY=Math.max(...dates.map(l=>l.y));let headers=texts.filter(i=>i.vertical&&i.y>firstY&&/\p{L}/u.test(i.s)).sort((a,b)=>a.x-b.x);if(!headers.length){const h=lines.filter(l=>l.y>firstY&&l.items.filter(i=>/\p{L}/u.test(i.s)).length>=2).sort((a,b)=>a.y-b.y)[0];if(h)headers=h.items.filter(i=>/\p{L}/u.test(i.s)&&!/^\d/.test(i.s))}if(headers.length<2)throw Error('Die Namensspalten konnten nicht sicher erkannt werden. Bitte einen Dienstplan mit Namen je Spalte verwenden.');return headers.map((h,index)=>{const x=h.x+(h.vertical?0:h.w/2);const left=index===0?x-(headers[1].x-h.x)/2:(headers[index-1].x+x)/2;const right=index===headers.length-1?x+(x-headers[index-1].x)/2:(x+headers[index+1].x)/2;const entries=dates.map(l=>{const raw=l.items.filter(i=>i.x+i.w/2>left&&i.x+i.w/2<right).map(i=>i.s).join(' ').trim();if(!raw)throw Error('Mindestens eine Dienstplanzelle ist leer. Bitte die Datei prüfen; ein unsicherer Plan wird nicht exportiert.');return {date:l.date,raw}});return {name:h.s,entries}})}
export function mergePages(pages){const people=new Map();for(const page of pages)for(const p of page){if(!people.has(p.name))people.set(p.name,{name:p.name,entries:[]});const list=people.get(p.name).entries;for(const e of p.entries){const prior=list.find(x=>x.date===e.date);if(prior&&prior.raw!==e.raw)throw Error('Widersprüchliche Dienste für denselben Tag gefunden. Bitte nur eine Planversion importieren.');if(!prior)list.push(e)}}return [...people.values()].map(p=>({...p,entries:p.entries.sort((a,b)=>a.date.localeCompare(b.date))}))}
export function classify(raw){const text=raw.trim();if(/^frei$/i.test(text))return {kind:'absence',label:'Frei'};if(/^(u|urlaub)$/i.test(text))return {kind:'absence',label:'Urlaub'};const t=text.match(/^(\d{1,2})(?::?(\d{2}))?\s*([a-zäöü]*)$/i);if(t){const hour=+t[1],minute=+(t[2]||0);if(hour<24&&minute<60)return {kind:'timed',time:`${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`,label:t[3]?`Dienst · ${t[3]}`:'Dienst'}}return {kind:'allDay',label:({office:'Office',poker:'Poker',sem:'Seminar'})[text.toLowerCase()]||text}}
